//! Parity tests for `filter_unseen_df` (`tests/fixtures/filter_unseen_df.json`, generated by
//! `tests/fixtures/gen_filter_unseen_df.py`).

mod common;

use common::{cases, compare_frame, decode_frame, load_fixture};
use indexmap::IndexMap;
use meerschaum_kernel::diff::{FilterUnseenOptions, filter_unseen_df};

#[test]
fn filter_unseen_df_parity() {
    let fixture = load_fixture("filter_unseen_df");
    let mut failures = Vec::new();
    for case in cases(&fixture) {
        let name = case["name"].as_str().unwrap();
        let old = (!case["old"].is_null()).then(|| decode_frame(&case["old"]));
        let new = decode_frame(&case["new"]);
        let dtypes: Option<IndexMap<String, String>> = case["dtypes"].as_object().map(|o| {
            o.iter()
                .map(|(k, v)| (k.clone(), v.as_str().unwrap().to_string()))
                .collect()
        });
        let opts = FilterUnseenOptions {
            dtypes,
            coerce_mixed_numerics: case["kwargs"]["coerce_mixed_numerics"]
                .as_bool()
                .unwrap_or(true),
        };
        let out = filter_unseen_df(old.as_ref(), &new, &opts);
        if let Err(m) = compare_frame(&case["ok"], &out, name) {
            failures.push(m);
        }
    }
    // Guard against a vacuous comparator: most deltas differ from the full new frame.
    let detected = cases(&fixture)
        .iter()
        .filter(|c| compare_frame(&c["ok"], &decode_frame(&c["new"]), "self-check").is_err())
        .count();
    assert!(
        detected >= 20,
        "comparator detected only {detected} filtered outputs"
    );
    if !failures.is_empty() {
        panic!(
            "{} filter_unseen_df parity failures:\n{}",
            failures.len(),
            failures.join("\n")
        );
    }
}
